CREATE OR REPLACE FUNCTION public.actualizar_fecha_actualizacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.fecha_actualizacion = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fecha_entrega_disponible(p_fecha_entrega date, p_momento timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dia public.dias_entrega%rowtype;
  v_ahora_local timestamp;
  v_fecha_local date;
  v_deadline timestamp;
begin
  if p_fecha_entrega is null then
    return false;
  end if;

  v_ahora_local := p_momento at time zone 'America/Santiago';
  v_fecha_local := v_ahora_local::date;

  if p_fecha_entrega < v_fecha_local
    or p_fecha_entrega > v_fecha_local + 14 then
    return false;
  end if;

  select * into v_dia
  from public.dias_entrega d
  where d.dia_semana = extract(isodow from p_fecha_entrega)::smallint
    and d.activo = true;

  if not found then
    return false;
  end if;

  v_deadline := (p_fecha_entrega - v_dia.dias_anticipacion_corte) + v_dia.hora_corte;
  return v_ahora_local < v_deadline;
end;
$function$

CREATE OR REPLACE FUNCTION operativo_privado.completar_operacion(p_pedido_id uuid, p_version_esperada bigint, p_clave uuid, p_operacion text, p_solicitud jsonb, p_item_pedido_id uuid, p_motivo text, p_anteriores jsonb, p_nuevos jsonb, p_resultado jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_inicio jsonb;
  v_version bigint;
begin
  v_inicio := operativo_privado.iniciar_operacion(p_pedido_id, p_version_esperada,
    p_clave, p_operacion, p_solicitud);
  if (v_inicio ->> 'reintento')::boolean then return v_inicio; end if;
  if p_motivo is null or btrim(p_motivo) = '' or length(p_motivo) > 2000
    or p_anteriores is null or jsonb_typeof(p_anteriores) <> 'object'
    or p_nuevos is null or jsonb_typeof(p_nuevos) <> 'object'
    or p_resultado is null or jsonb_typeof(p_resultado) <> 'object' then
    raise exception 'AUDITORIA_OPERATIVA_INVALIDA';
  end if;
  if p_item_pedido_id is not null then
    perform 1 from public.items_pedido i
      where i.id = p_item_pedido_id and i.pedido_id = p_pedido_id for share;
    if not found then raise exception 'ITEM_PEDIDO_NO_CORRESPONDE_AL_PEDIDO'; end if;
  end if;
  update operativo_privado.versiones_pedido v set version = v.version + 1
    where v.pedido_id = p_pedido_id and v.version = p_version_esperada
    returning v.version into v_version;
  if not found then raise exception 'VERSION_OPERATIVA_CONFLICTO'; end if;
  insert into operativo_privado.historial_operativo (
    pedido_id, item_pedido_id, operacion, actor_id, motivo, valores_anteriores,
    valores_nuevos, version, clave_idempotencia, version_esperada, solicitud, resultado
  ) values (p_pedido_id, p_item_pedido_id, p_operacion, auth.uid(), p_motivo,
    p_anteriores, p_nuevos, v_version, p_clave, p_version_esperada, p_solicitud, p_resultado);
  return jsonb_build_object('reintento', false, 'resultado', p_resultado, 'version', v_version);
end;
$function$

CREATE OR REPLACE FUNCTION operativo_privado.exigir_pedido_reprogramable(p_pedido_id uuid)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p public.pedidos%rowtype; cp operativo_privado.carga_pedidos%rowtype;
 c operativo_privado.cargas%rowtype; intento jsonb;
 fallo operativo_privado.historial_operativo%rowtype; version_actual bigint;
begin
 select * into p from public.pedidos where id=p_pedido_id;
 if not found then raise exception 'PEDIDO_NO_ENCONTRADO'; end if;
 if p.estado is distinct from 'entrega_fallida' or p.preparacion_finalizada_en is null
 or p.venta_definitiva_snapshot is not null or p.venta_reconocida_en is not null
 or exists(select 1 from operativo_privado.entregas_definitivas where pedido_id=p.id) then
 raise exception 'PEDIDO_NO_REPROGRAMABLE'; end if;
 select * into cp from operativo_privado.carga_pedidos where pedido_id=p.id;
 if not found or not cp.incluido then raise exception 'PEDIDO_NO_REPROGRAMABLE'; end if;
 select * into c from operativo_privado.cargas where fecha=cp.fecha;
 if not found or c.estado is distinct from 'cerrada' then raise exception 'CIERRE_REQUERIDO'; end if;
 select coalesce((select version from operativo_privado.versiones_pedido where pedido_id=p.id),0) into version_actual;
 -- No trasladar una selección sin su intento cerrado y evento de fallo exactos.
 -- La versión del cierre puede preceder otras operaciones auditadas sin cambio
 -- de estado; se enlaza el fallo por su propia versión, no por la versión actual.
 select x into intento from jsonb_array_elements(c.resumen_cierre->'intentos') x
 where x->'pedido'->>'id'=p.id::text;
 select * into fallo from operativo_privado.historial_operativo
 where pedido_id=p.id and operacion='entrega_fallida' order by version desc limit 1;
 if intento is null or fallo.pedido_id is null
 or intento->'pedido' is distinct from to_jsonb(p)
 or intento->'seleccion' is distinct from to_jsonb(cp)
 or intento->'fallo' is distinct from to_jsonb(fallo)
 or jsonb_typeof(intento->'version') is distinct from 'number'
 or (intento->>'version')::bigint>version_actual
 or intento->'motivo' is distinct from to_jsonb(fallo.motivo)
 or fallo.version>(intento->>'version')::bigint
 or fallo.valores_nuevos->>'estado' is distinct from 'entrega_fallida'
 or not exists(select 1 from operativo_privado.historial_cargas h
 where h.fecha=cp.fecha and h.version=c.version and h.resultado=c.resumen_cierre
 and h.solicitud->>'accion'='cerrar') then
 raise exception 'TRAZABILIDAD_INTENTO_INVALIDA'; end if;
 return cp.fecha;
end; $function$

CREATE OR REPLACE FUNCTION operativo_privado.fecha_reprogramacion_admite_pedidos(p_fecha date)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare abierta boolean; incorpora boolean;
begin
 if operativo_privado.fecha_reprogramacion_tiene_rutas_multi(p_fecha) then
 if exists(select 1 from operativo_privado.cargas where fecha=p_fecha) then return false; end if;
 -- Fase 2 no ofrece incorporar en reparto; no prometer esa posibilidad.
 select md5(replace(prosrc,chr(13)||chr(10),chr(10))) in ('3258c2545d0c9dd5960f60bf1d0d103b','d8c2db86f702c3a1174dd1374207009d') into incorpora
 from pg_proc where oid=to_regprocedure('public.operar_ruta_multiple(jsonb)');
 execute 'select exists(select 1 from operativo_privado.rutas_multi where fecha=$1 and (estado in (''planificacion'',''preparacion'') or (estado=''en_reparto'' and $2 and fecha=(statement_timestamp() at time zone ''America/Santiago'')::date and exists(select 1 from operativo_privado.ruta_multi_repartidores a join operativo_privado.repartidores rp on rp.usuario_id=a.usuario_id and rp.activo where a.ruta_id=rutas_multi.id))))'
 into abierta using p_fecha,coalesce(incorpora,false);
 return abierta;
 end if;
 return not exists(select 1 from operativo_privado.cargas where fecha=p_fecha and estado<>'preparacion');
end; $function$

CREATE OR REPLACE FUNCTION operativo_privado.fecha_reprogramacion_tiene_rutas_multi(p_fecha date)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare existe boolean;
begin
 if to_regclass('operativo_privado.rutas_multi') is null then return false; end if;
 execute 'select exists(select 1 from operativo_privado.rutas_multi where fecha=$1)' into existe using p_fecha;
 return existe;
end; $function$

CREATE OR REPLACE FUNCTION operativo_privado.iniciar_operacion(p_pedido_id uuid, p_version_esperada bigint, p_clave uuid, p_operacion text, p_solicitud jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_evento operativo_privado.historial_operativo%rowtype;
  v_version bigint;
begin
  -- Defensa adicional: el permiso de negocio no sustituye las ACL privadas.
  -- Se limita la infraestructura inicial a operaciones administrativas futuras.
  if v_actor is null or not coalesce((public.es_admin() or operativo_privado.permiso_reparto(p_pedido_id,null)), false) then
    raise exception 'NO_AUTORIZADO';
  end if;
  if p_pedido_id is null or p_clave is null or p_version_esperada is null
    or p_version_esperada < 0 or p_operacion is null
    or btrim(p_operacion) = '' or length(p_operacion) > 100
    or p_solicitud is null or jsonb_typeof(p_solicitud) <> 'object' then
    raise exception 'OPERACION_INVALIDA';
  end if;
  -- Lock común por pedido, incluso cuando todavía no hay versión privada.
  perform 1 from public.pedidos p where p.id = p_pedido_id for update;
  if not found then raise exception 'PEDIDO_NO_ENCONTRADO'; end if;

  select h.* into v_evento from operativo_privado.historial_operativo h
    where h.pedido_id = p_pedido_id and h.clave_idempotencia = p_clave;
  if found then
    if v_evento.actor_id is distinct from v_actor
      or v_evento.operacion is distinct from p_operacion
      or v_evento.solicitud is distinct from p_solicitud
      or v_evento.version_esperada is distinct from p_version_esperada then
      raise exception 'CLAVE_IDEMPOTENCIA_EN_USO';
    end if;
    -- Reintento antes de comparar versión actual: respuesta original estable.
    return jsonb_build_object('reintento', true, 'resultado', v_evento.resultado,
      'version', v_evento.version);
  end if;
  insert into operativo_privado.versiones_pedido (pedido_id) values (p_pedido_id)
    on conflict (pedido_id) do nothing;
  select v.version into v_version from operativo_privado.versiones_pedido v
    where v.pedido_id = p_pedido_id for update;
  if v_version <> p_version_esperada then raise exception 'VERSION_OPERATIVA_CONFLICTO'; end if;
  return jsonb_build_object('reintento', false, 'version', v_version);
end;
$function$

CREATE OR REPLACE FUNCTION operativo_privado.permite_reprogramacion(p_tabla oid, p_antes jsonb, p_despues jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
AS $function$
declare r operativo_privado.permiso_reprogramacion%rowtype; omitidas text[];
begin
 select * into r from operativo_privado.permiso_reprogramacion
 where pedido_id=coalesce(p_antes->>'pedido_id',p_antes->>'id')::uuid
 and transaccion=txid_current() and actor=auth.uid();
 if not found or auth.uid() is null or not coalesce(public.es_admin(),false) then return false; end if;
 if p_tabla='public.pedidos'::regclass then
 select array['fecha_actualizacion']::text[] || coalesce(array_agg(attname::text),array[]::text[])
 into omitidas from pg_attribute where attrelid=p_tabla and attnum>0 and not attisdropped and attgenerated<>'';
 return (p_antes-omitidas)=(r.pedido_antes-omitidas)
 and (p_despues-omitidas)=(r.pedido_despues-omitidas);
 elsif p_tabla='operativo_privado.carga_pedidos'::regclass then
 return p_antes=r.seleccion_antes and p_despues=r.seleccion_despues;
 end if;
 return false;
end; $function$

CREATE OR REPLACE FUNCTION operativo_privado.proteger_cierre_carga()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
AS $function$
begin
 -- Una snapshot REPEATABLE READ anterior al cierre podría ocultarlo en triggers.
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'AISLAMIENTO_NO_COMPATIBLE'; end if;
 if TG_TABLE_NAME='cargas' then
 if old.estado='cerrada' then raise exception 'RUTA_CERRADA'; end if;
 else
 -- Bloquea AMBAS jornadas, en orden, al trasladar una selección.
 perform 1 from operativo_privado.cargas
 where fecha in (case when TG_OP='INSERT' then new.fecha else old.fecha end,
 case when TG_OP='DELETE' then old.fecha else new.fecha end) order by fecha for update;
 if TG_OP='DELETE' and operativo_privado.permite_reprogramacion(TG_RELID,to_jsonb(old),'null'::jsonb) then return old; end if;
 if TG_OP='UPDATE' and operativo_privado.permite_reprogramacion(TG_RELID,to_jsonb(old),to_jsonb(new)) then return new; end if;
 if exists(select 1 from operativo_privado.cargas where estado='cerrada'
 and (fecha=case when TG_OP='INSERT' then new.fecha else old.fecha end
 or fecha=case when TG_OP='DELETE' then old.fecha else new.fecha end)) then raise exception 'RUTA_CERRADA'; end if;
 end if;
 if TG_OP='DELETE' then return old; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION operativo_privado.proteger_contratos_multi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare j jsonb; viejo jsonb;
begin
 if TG_OP<>'DELETE' then j:=to_jsonb(new); end if;
 if TG_OP<>'INSERT' then viejo:=to_jsonb(old); end if;
 if TG_TABLE_NAME in ('cargas','carga_pedidos') then
 perform operativo_privado.exigir_fecha_legacy((coalesce(j,viejo)->>'fecha')::date);
 if viejo is not null then perform operativo_privado.exigir_fecha_legacy((viejo->>'fecha')::date); end if;
 elsif TG_TABLE_NAME='rutas' then
 if exists(select 1 from operativo_privado.rutas_multi where id in ((j->>'id')::uuid,(viejo->>'id')::uuid)) then raise exception 'REQUIERE_RUTA_INDIVIDUAL'; end if;
 elsif TG_TABLE_NAME='paradas_ruta' then
 if exists(select 1 from operativo_privado.rutas_multi where id in ((j->>'ruta_id')::uuid,(viejo->>'ruta_id')::uuid))
 or exists(select 1 from operativo_privado.ruta_multi_pedidos where pedido_id in ((j->>'pedido_id')::uuid,(viejo->>'pedido_id')::uuid)) then raise exception 'REQUIERE_RUTA_INDIVIDUAL'; end if;
 elsif TG_TABLE_NAME='reparto_asignaciones' then
 perform operativo_privado.exigir_fecha_legacy((coalesce(j,viejo)->>'fecha')::date);
 end if;
 if TG_OP='DELETE' then return old; else return new; end if;
end $function$

CREATE OR REPLACE FUNCTION operativo_privado.proteger_pedido_cargado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare e text; omitidas text[];
begin
 select c.estado into e from operativo_privado.cargas c join operativo_privado.carga_pedidos cp on cp.fecha=c.fecha where cp.pedido_id=old.id and cp.incluido;
 select array['estado','fecha_actualizacion']::text[] || coalesce(array_agg(a.attname::text),array[]::text[])
 into omitidas from pg_catalog.pg_attribute a
 where a.attrelid=TG_RELID and a.attnum>0 and not a.attisdropped and a.attgenerated<>'';
 if e='en_ruta' and old.estado='en_reparto' and new.estado='entregado'
 and exists(select 1 from operativo_privado.entregas_definitivas d where d.pedido_id=old.id
   and d.snapshot=new.venta_definitiva_snapshot and d.instante=new.venta_reconocida_en) then
   omitidas:=omitidas || array['venta_definitiva_snapshot','venta_reconocida_en']::text[];
 end if;
 if e in ('lista','en_ruta') and (to_jsonb(new)-omitidas) is distinct from (to_jsonb(old)-omitidas) then raise exception 'CARGA_CONFIRMADA'; end if;
 if e='lista' and new.estado not in ('listo_despacho','en_reparto') then raise exception 'CARGA_CONFIRMADA'; end if;
 if e='en_ruta' and new.estado in ('recibido','en_revision','programado','confirmado','preparando','listo_despacho') then raise exception 'CARGA_YA_SALIO'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION operativo_privado.proteger_pedido_ruta_cerrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
AS $function$
begin
 -- Una snapshot REPEATABLE READ anterior al cierre podría ocultarlo en triggers.
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'AISLAMIENTO_NO_COMPATIBLE'; end if;
 if TG_OP='UPDATE' and operativo_privado.permite_reprogramacion(TG_RELID,to_jsonb(old),to_jsonb(new)) then return new; end if;
 if exists(select 1 from operativo_privado.carga_pedidos cp join operativo_privado.cargas c using(fecha)
 where cp.pedido_id=old.id and cp.incluido and c.estado='cerrada') then raise exception 'RUTA_CERRADA'; end if;
 if TG_OP='DELETE' then return old; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION operativo_privado.proteger_ruta_multi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare pid uuid; r operativo_privado.rutas_multi%rowtype; omitidas text[];
begin
 if TG_TABLE_NAME<>'pedidos' and TG_OP='UPDATE' then
 if old.pedido_id is distinct from new.pedido_id and exists(select 1 from operativo_privado.ruta_multi_pedidos where pedido_id in (old.pedido_id,new.pedido_id)) then raise exception 'PERTENENCIA_INMUTABLE'; end if;
 end if;
 if TG_TABLE_NAME='pedidos' then pid:=old.id;
 elsif TG_OP='DELETE' then pid:=old.pedido_id;
 else pid:=new.pedido_id; end if;
 -- Lock común del pedido también para INSERT/DELETE de líneas, sin invertir
 -- el orden de RPC legacy: abortar ante contención y reintentar la operación.
 perform 1 from public.pedidos where id=pid for update nowait;
 select rm.* into r from operativo_privado.ruta_multi_pedidos m join operativo_privado.rutas_multi rm on rm.id=m.ruta_id where m.pedido_id=pid;
 if not found then
 if TG_OP='DELETE' then return old; else return new; end if;
 end if;
 if TG_TABLE_NAME<>'pedidos' then
 if TG_OP='UPDATE' and old.pedido_id is distinct from new.pedido_id then raise exception 'PERTENENCIA_INMUTABLE'; end if;
 if r.estado in ('en_reparto','cerrada') or (TG_TABLE_NAME='preparacion_items_pedido' and r.estado<>'preparacion') then raise exception 'RUTA_NO_EDITABLE'; end if;
 elsif TG_OP='DELETE' then raise exception 'PEDIDO_ASIGNADO_A_RUTA';
 else
 if r.estado='planificacion' and new.estado='preparando' and old.estado is distinct from new.estado then raise exception 'RUTA_NO_EDITABLE'; end if;
 if new.fecha_entrega is distinct from old.fecha_entrega then raise exception 'PEDIDO_ASIGNADO_A_RUTA'; end if;
 if r.estado='cerrada' and to_jsonb(new) is distinct from to_jsonb(old) then raise exception 'RUTA_NO_EDITABLE'; end if;
 if new.estado='en_reparto' and old.estado is distinct from new.estado and not exists(
 select 1 from operativo_privado.ruta_multi_capacidad c where c.transaccion=txid_current() and c.actor=auth.uid() and c.ruta_id=r.id and c.pedido_id=pid and c.accion='salir') then raise exception 'SALIDA_REQUIERE_RUTA'; end if;
 if r.estado='en_reparto' then
 select array['estado','fecha_actualizacion','venta_definitiva_snapshot','venta_reconocida_en']::text[] || coalesce(array_agg(attname::text),array[]::text[]) into omitidas
 from pg_attribute where attrelid=TG_RELID and attnum>0 and not attisdropped and attgenerated<>'';
 if (to_jsonb(new)-omitidas) is distinct from (to_jsonb(old)-omitidas) or new.estado not in ('en_reparto','entregado','entrega_fallida') then raise exception 'RUTA_NO_EDITABLE'; end if;
 end if;
 end if;
 if TG_OP='DELETE' then return old; else return new; end if;
end $function$

CREATE OR REPLACE FUNCTION public.proteger_regimen_contable_pedido()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if new.regimen_contable is distinct from old.regimen_contable then
    raise exception 'REGIMEN_CONTABLE_INMUTABLE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.operar_carga_jornada(p_fecha date, p_version bigint, p_clave uuid, p_accion text, p_pedidos jsonb, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
 c operativo_privado.cargas%rowtype; h operativo_privado.historial_cargas%rowtype;
 s jsonb; anterior jsonb; resultado jsonb; e jsonb; p public.pedidos%rowtype;
 pv bigint; inicio jsonb;
begin perform operativo_privado.exigir_fecha_legacy(p_fecha);
 if auth.uid() is null or not coalesce(public.es_admin(),false) then raise exception 'NO_AUTORIZADO'; end if;
 if p_fecha is null or not isfinite(p_fecha) or p_version is null or p_version<0 or p_clave is null
 or p_accion is null or p_accion not in ('guardar','confirmar','salir','reabrir') then raise exception 'OPERACION_INVALIDA'; end if;
 -- Antes de cualquier lock de fila/advisory: estabiliza el universo de la fecha
 -- frente a INSERT y cambios legacy que no participan del lock de jornada.
 -- EXCLUSIVE también espera SELECT FOR UPDATE legacy antes de tomar el
 -- lock: evita retenerlo esperando una fila cuyo dueño aún necesita UPDATE.
 -- SELECT ordinarios siguen permitidos. El coste es serializar escrituras.
 lock table public.pedidos in exclusive mode;
 perform pg_advisory_xact_lock(hashtextextended('carga:'||p_fecha::text,0));
 s:=jsonb_build_object('accion',p_accion,'pedidos',p_pedidos,'motivo',p_motivo,'version',p_version);
 select * into h from operativo_privado.historial_cargas where fecha=p_fecha and clave=p_clave;
 if found then
 if h.actor<>auth.uid() or h.solicitud<>s then raise exception 'CLAVE_IDEMPOTENCIA_EN_USO'; end if;
 return h.resultado;
 end if;
 if p_fecha is distinct from (clock_timestamp() at time zone 'America/Santiago')::date then raise exception 'PREPARACION_FECHA_NO_HABILITADA'; end if;
 insert into operativo_privado.cargas(fecha) values(p_fecha) on conflict do nothing;
 select * into c from operativo_privado.cargas where fecha=p_fecha for update;
 if c.version<>p_version then raise exception 'VERSION_CARGA_CONFLICTO'; end if;
 if c.estado='en_ruta' then raise exception 'CARGA_YA_SALIO'; end if;
 anterior:=public.leer_carga_jornada(p_fecha);
 if p_accion='guardar' then
 if c.estado<>'preparacion' then raise exception 'CARGA_NO_EDITABLE'; end if;
 if p_pedidos is null or jsonb_typeof(p_pedidos)<>'array' or jsonb_array_length(p_pedidos)=0 then raise exception 'SELECCION_REQUERIDA'; end if;
 if exists(select 1 from jsonb_array_elements(p_pedidos) x where jsonb_typeof(x)<>'object'
 or x->>'id' is null or jsonb_typeof(x->'incluido') is distinct from 'boolean')
 or (select count(distinct x->>'id') from jsonb_array_elements(p_pedidos) x)<>jsonb_array_length(p_pedidos) then raise exception 'SELECCION_INVALIDA'; end if;
 -- Bloqueo común con las RPC individuales; orden determinista.
 perform 1 from public.pedidos where id in (select (x->>'id')::uuid from jsonb_array_elements(p_pedidos) x) order by id for update;
 if (select count(*) from public.pedidos pe where pe.id in (select (x->>'id')::uuid from jsonb_array_elements(p_pedidos) x)
 and (pe.fecha_entrega=p_fecha or exists(select 1 from operativo_privado.carga_pedidos cp where cp.pedido_id=pe.id and cp.fecha=p_fecha)))<>jsonb_array_length(p_pedidos) then raise exception 'SELECCION_INVALIDA'; end if;
 -- Cancelados/terminales o miembros desplazados sólo admiten exclusión explícita.
 if exists(select 1 from jsonb_array_elements(p_pedidos) x join public.pedidos pe on pe.id=(x->>'id')::uuid
 where (x->>'incluido')::boolean and (pe.fecha_entrega is distinct from p_fecha
 or pe.estado not in ('recibido','en_revision','programado','confirmado','preparando','listo_despacho'))) then raise exception 'SELECCION_INVALIDA'; end if;
 if exists(select 1 from jsonb_array_elements(p_pedidos) x where not (x->>'incluido')::boolean
 and (nullif(btrim(x->>'motivo'),'') is null or length(x->>'motivo')>2000)) then raise exception 'EXCLUSION_REQUIERE_MOTIVO'; end if;
 -- No permite omitir silenciosamente miembros persistidos: excluir con motivo.
 if exists(select 1 from operativo_privado.carga_pedidos cp where cp.fecha=p_fecha and not exists(select 1 from jsonb_array_elements(p_pedidos) x where (x->>'id')::uuid=cp.pedido_id)) then raise exception 'EXCLUSION_REQUIERE_MOTIVO'; end if;
 for e in select value from jsonb_array_elements(p_pedidos) loop
 insert into operativo_privado.carga_pedidos(fecha,pedido_id,incluido,motivo)
 values(p_fecha,(e->>'id')::uuid,(e->>'incluido')::boolean,nullif(btrim(e->>'motivo'),''))
 on conflict(pedido_id) do update set incluido=excluded.incluido,motivo=excluded.motivo
 where operativo_privado.carga_pedidos.fecha=p_fecha;
 if not found then raise exception 'PEDIDO_EN_OTRA_CARGA'; end if;
 end loop;
 else
 if p_accion in ('confirmar','salir') and not exists(select 1 from operativo_privado.carga_pedidos where fecha=p_fecha and incluido) then raise exception 'CARGA_VACIA'; end if;
 if (p_accion='confirmar' and c.estado<>'preparacion') or (p_accion in ('salir','reabrir') and c.estado<>'lista') then raise exception 'ESTADO_CARGA_INVALIDO'; end if;
 if p_accion='reabrir' and (nullif(btrim(p_motivo),'') is null or length(p_motivo)>2000) then raise exception 'MOTIVO_REQUERIDO'; end if;
 -- Confirmar exige una decisión persistida para CADA pedido que existe ahora.
 -- Los creados después de esta transacción quedan fuera; salir no los incorpora.
 if p_accion='confirmar' and exists(select 1 from public.pedidos pe where pe.fecha_entrega=p_fecha
 and not exists(select 1 from operativo_privado.carga_pedidos cp where cp.fecha=p_fecha and cp.pedido_id=pe.id)) then raise exception 'DECISIONES_PENDIENTES'; end if;
 -- Lista congela los pedidos incluidos. Reabrir libera el cierre sin borrar líneas.
 if p_accion='reabrir' then update operativo_privado.cargas set estado='preparacion',confirmada_en=null where fecha=p_fecha; end if;
 for p in select pe.* from public.pedidos pe join operativo_privado.carga_pedidos cp on cp.pedido_id=pe.id
 where cp.fecha=p_fecha and cp.incluido order by pe.id for update of pe loop
 if p.estado<>'listo_despacho' or p.fecha_entrega is distinct from p_fecha then raise exception 'PEDIDO_NO_LISTO'; end if;
 if p_accion in ('confirmar','salir') then
 perform 1 from public.items_pedido where pedido_id=p.id order by id for update;
 perform 1 from public.preparacion_items_pedido where pedido_id=p.id order by item_pedido_id for update;
 if p.preparacion_finalizada_en is null or not exists(select 1 from public.items_pedido where pedido_id=p.id)
 or exists(select 1 from public.items_pedido i left join public.preparacion_items_pedido pi on pi.item_pedido_id=i.id
 where i.pedido_id=p.id and (not coalesce(pi.confirmado_explicito,false) or pi.importe_linea_operativo is null)) then raise exception 'PRODUCTOS_PENDIENTES'; end if;
 end if;
 if p_accion in ('salir','reabrir') then
 select coalesce((select version from operativo_privado.versiones_pedido where pedido_id=p.id),0) into pv;
 inicio:=operativo_privado.iniciar_operacion(p.id,pv,p_clave,'carga_'||p_accion,s);
 update public.pedidos set estado=case when p_accion='salir' then 'en_reparto'::public.estado_pedido else 'preparando'::public.estado_pedido end,
 preparacion_finalizada_en=case when p_accion='reabrir' then null else preparacion_finalizada_en end,
 preparacion_finalizada_por=case when p_accion='reabrir' then null else preparacion_finalizada_por end,
 preparacion_estado=case when p_accion='reabrir' then 'pendiente' else preparacion_estado end where id=p.id;
 perform operativo_privado.completar_operacion(p.id,pv,p_clave,'carga_'||p_accion,s,null,
 coalesce(nullif(btrim(p_motivo),''),'Salida global de carga confirmada'),to_jsonb(p),
 jsonb_build_object('estado',case when p_accion='salir' then 'en_reparto' else 'preparando' end),jsonb_build_object('fecha',p_fecha));
 end if;
 end loop;
 -- Evaluación tras todos los locks, también si se cruzó medianoche.
 if p_fecha is distinct from (clock_timestamp() at time zone 'America/Santiago')::date then raise exception 'PREPARACION_FECHA_NO_HABILITADA'; end if;
 update operativo_privado.cargas set estado=case p_accion when 'confirmar' then 'lista' when 'salir' then 'en_ruta' else 'preparacion' end,
 confirmada_en=case when p_accion='confirmar' then clock_timestamp() else confirmada_en end,
 salida_en=case when p_accion='salir' then clock_timestamp() else salida_en end where fecha=p_fecha;
 end if;
 -- También guardar revalida el reloj después de todos sus locks/escrituras.
 if p_fecha is distinct from (clock_timestamp() at time zone 'America/Santiago')::date then raise exception 'PREPARACION_FECHA_NO_HABILITADA'; end if;
 update operativo_privado.cargas set version=version+1 where fecha=p_fecha;
 resultado:=public.leer_carga_jornada(p_fecha)-'historial';
 insert into operativo_privado.historial_cargas(fecha,version,clave,actor,solicitud,anterior,resultado)
 values(p_fecha,p_version+1,p_clave,auth.uid(),s,anterior-'historial',resultado);
 return resultado;
end; $function$

CREATE OR REPLACE FUNCTION public.operar_ruta_multiple(p_solicitud jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
AS $function$
declare s jsonb:=p_solicitud; accion text:=s->>'accion'; rid uuid:=(s->>'ruta')::uuid;
 f date:=(s->>'fecha')::date; clave uuid:=(s->>'clave')::uuid; ver bigint:=(s->>'version')::bigint;
 r operativo_privado.rutas_multi%rowtype; h operativo_privado.ruta_multi_eventos%rowtype;
 p public.pedidos%rowtype; pv bigint; antes jsonb; resultado jsonb; cantidades jsonb; prep text; ids uuid[]; us uuid[];
 esadmin boolean; it jsonb; hist operativo_privado.historial_operativo%rowtype;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'AISLAMIENTO_NO_COMPATIBLE'; end if;
 esadmin:=auth.uid() is not null and coalesce(public.es_admin(),false);
 if auth.uid() is null or (not esadmin and not public.acceso_repartidor()) then raise exception 'NO_AUTORIZADO'; end if;
 if s is null or jsonb_typeof(s)<>'object' or rid is null or f is null or not isfinite(f) or clave is null or ver is null or ver<0
 or accion is null or accion not in ('crear','seleccionar','asignar','preparar','salir','cerrar','ordenar','entregar','fallida','incorporar') then raise exception 'OPERACION_INVALIDA'; end if;
 -- Serializa con RPC anteriores y preparación. NOWAIT evita ciclos cliente ->
 -- pedido de las RPC contables: un conflicto revierte sin efectos parciales.
 lock table public.pedidos in exclusive mode nowait;
 perform pg_advisory_xact_lock(582051005);
 if not esadmin and (accion not in ('entregar','fallida','cerrar') or not exists(
 select 1 from operativo_privado.ruta_multi_repartidores a join operativo_privado.repartidores rp on rp.usuario_id=a.usuario_id and rp.activo
 join operativo_privado.rutas_multi rm on rm.id=a.ruta_id where a.ruta_id=rid and a.usuario_id=auth.uid() and rm.fecha=f)) then raise exception 'NO_AUTORIZADO'; end if;
 select e.* into h from operativo_privado.ruta_multi_eventos e where e.clave=(s->>'clave')::uuid;
 if found then
 if h.actor<>auth.uid() or h.solicitud<>s then raise exception 'CLAVE_IDEMPOTENCIA_EN_USO'; end if;
 return h.resultado - 'snapshot';
 end if;
 if exists(select 1 from operativo_privado.cargas where fecha=f) then raise exception 'JORNADA_LEGACY'; end if;
 if accion='crear' then
 if ver<>0 or nullif(btrim(s->>'nombre'),'') is null or length(btrim(s->>'nombre'))>100 then raise exception 'NOMBRE_INVALIDO'; end if;
 insert into public.rutas(id,fecha_operativa,nombre,creada_por) values(rid,f,btrim(s->>'nombre'),auth.uid());
 insert into operativo_privado.rutas_multi(id,fecha,nombre) values(rid,f,btrim(s->>'nombre'));
 end if;
 select * into r from operativo_privado.rutas_multi where id=rid for update;
 if not found or r.fecha<>f then raise exception 'RUTA_NO_ENCONTRADA'; end if;
 -- También consumir versión de ruta para invalidar asignaciones revocadas.
 if r.version<>ver then raise exception 'VERSION_RUTA_CONFLICTO'; end if;
 if r.estado='cerrada' or (r.estado='en_reparto' and accion not in ('cerrar','entregar','fallida','incorporar')) then raise exception 'RUTA_NO_EDITABLE'; end if;
 antes:=operativo_privado.snapshot_ruta_multi(rid);
 if accion='incorporar' then
 if not esadmin or r.estado<>'en_reparto' then raise exception 'NO_AUTORIZADO'; end if;
 if nullif(btrim(s->>'motivo'),'') is null or length(s->>'motivo')>2000 then raise exception 'MOTIVO_REQUERIDO'; end if;
 if f is distinct from (clock_timestamp() at time zone 'America/Santiago')::date then raise exception 'PREPARACION_FECHA_NO_HABILITADA'; end if;
 if jsonb_typeof(s->'pedidos') is distinct from 'array' or jsonb_array_length(s->'pedidos')=0 then raise exception 'SELECCION_INVALIDA'; end if;
 select array_agg(value::uuid) into ids from jsonb_array_elements_text(s->'pedidos');
 if cardinality(ids)<>(select count(distinct x) from unnest(ids) x)
 or exists(select 1 from operativo_privado.ruta_multi_pedidos where pedido_id=any(ids))
 or exists(select 1 from operativo_privado.carga_pedidos where pedido_id=any(ids))
 or (select count(*) from public.pedidos where id=any(ids) and fecha_entrega=f and estado='listo_despacho' and regimen_contable='entrega_v1')<>cardinality(ids) then raise exception 'SELECCION_INVALIDA'; end if;
 if not exists(select 1 from operativo_privado.ruta_multi_repartidores a join operativo_privado.repartidores rp on rp.usuario_id=a.usuario_id and rp.activo where a.ruta_id=rid) then raise exception 'REPARTIDORES_REQUERIDOS'; end if;
 -- Sólo agrega: no elimina miembros, no cambia asignaciones ni reabre entregas.
 insert into operativo_privado.ruta_multi_pedidos(pedido_id,ruta_id,posicion)
 select x,rid,(select coalesce(max(posicion),0) from operativo_privado.ruta_multi_pedidos where ruta_id=rid)+n::integer
 from unnest(ids) with ordinality q(x,n);
 for p in select pe.* from public.pedidos pe join operativo_privado.ruta_multi_pedidos m on m.pedido_id=pe.id where m.ruta_id=rid and pe.id=any(ids) order by pe.id for update of pe loop
 if p.regimen_contable<>'entrega_v1' then raise exception 'REGIMEN_CONTABLE_NO_COMPATIBLE'; end if;
 if p.fecha_entrega<>f or p.estado<>'listo_despacho' or p.preparacion_finalizada_en is null then raise exception 'PEDIDO_NO_LISTO'; end if;
 perform 1 from public.items_pedido where pedido_id=p.id order by id for update;
 perform 1 from public.preparacion_items_pedido where pedido_id=p.id order by item_pedido_id for update;
 if not exists(select 1 from public.items_pedido where pedido_id=p.id) or exists(select 1 from public.items_pedido i left join public.preparacion_items_pedido pi on pi.item_pedido_id=i.id
 where i.pedido_id=p.id and (not coalesce(pi.confirmado_explicito,false) or pi.cantidad_preparada is null or pi.importe_linea_operativo is null)) then raise exception 'PRODUCTOS_PENDIENTES'; end if;
 prep:=operativo_privado.estado_preparacion_multi(p.id);
 if prep<>'listo' then raise exception 'INCORPORACION_REQUIERE_LISTO'; end if;
 select coalesce((select version from operativo_privado.versiones_pedido where pedido_id=p.id),0) into pv;
 perform operativo_privado.iniciar_operacion(p.id,pv,clave,'ruta_multiple_incorporar',s);
 insert into operativo_privado.ruta_multi_capacidad values(txid_current(),auth.uid(),rid,p.id,'salir');
 update public.pedidos set estado='en_reparto' where id=p.id;
 delete from operativo_privado.ruta_multi_capacidad where transaccion=txid_current();
 perform operativo_privado.completar_operacion(p.id,pv,clave,'ruta_multiple_incorporar',s,null,btrim(s->>'motivo'),to_jsonb(p),
 jsonb_build_object('estado','en_reparto','preparacion',prep,'cantidades',operativo_privado.cantidades_ruta_multi(p.id)),jsonb_build_object('ruta',rid,'estado','en_reparto'));
 end loop;
 elsif accion in ('seleccionar','ordenar') then
 if jsonb_typeof(s->'pedidos') is distinct from 'array' then raise exception 'SELECCION_INVALIDA'; end if;
 select coalesce(array_agg(value::uuid),array[]::uuid[]) into ids from jsonb_array_elements_text(s->'pedidos');
 if cardinality(ids)<>(select count(distinct x) from unnest(ids) x) then raise exception 'SELECCION_INVALIDA'; end if;
 if accion='ordenar' and (select coalesce(array_agg(pedido_id order by pedido_id),array[]::uuid[]) from operativo_privado.ruta_multi_pedidos where ruta_id=rid)
 is distinct from (select coalesce(array_agg(x order by x),array[]::uuid[]) from unnest(ids) x) then raise exception 'SELECCION_INVALIDA'; end if;
 if exists(select 1 from operativo_privado.ruta_multi_pedidos where pedido_id=any(ids) and ruta_id<>rid) then raise exception 'PEDIDO_YA_ASIGNADO'; end if;
 if (select count(*) from public.pedidos where id=any(ids) and fecha_entrega=f and estado in ('recibido','en_revision','programado','confirmado','preparando','listo_despacho'))<>cardinality(ids)
 or exists(select 1 from operativo_privado.carga_pedidos where pedido_id=any(ids)) then raise exception 'SELECCION_INVALIDA'; end if;
 delete from operativo_privado.ruta_multi_autorizaciones where ruta_id=rid and not(pedido_id=any(ids));
 delete from operativo_privado.ruta_multi_pedidos where ruta_id=rid;
 insert into operativo_privado.ruta_multi_pedidos(pedido_id,ruta_id,posicion) select x,rid,n::integer from unnest(ids) with ordinality u(x,n);
 elsif accion='asignar' then
 if jsonb_typeof(s->'repartidores') is distinct from 'array' then raise exception 'REPARTIDOR_NO_HABILITADO'; end if;
 select coalesce(array_agg(value::uuid),array[]::uuid[]) into us from jsonb_array_elements_text(s->'repartidores');
 if cardinality(us)<>(select count(*) from operativo_privado.repartidores rp join public.perfiles pf on pf.usuario_id=rp.usuario_id where rp.usuario_id=any(us) and rp.activo and pf.rol<>'admin') then raise exception 'REPARTIDOR_NO_HABILITADO'; end if;
 delete from operativo_privado.ruta_multi_repartidores where ruta_id=rid;
 insert into operativo_privado.ruta_multi_repartidores select rid,x from unnest(us) x;
 elsif accion='preparar' then
 if f is distinct from (clock_timestamp() at time zone 'America/Santiago')::date then raise exception 'PREPARACION_FECHA_NO_HABILITADA'; end if;
 if r.estado<>'planificacion' then raise exception 'RUTA_NO_EDITABLE'; end if;
 update operativo_privado.rutas_multi set estado='preparacion' where id=rid;
 elsif accion='salir' then
 if r.estado<>'preparacion' then raise exception 'RUTA_NO_EDITABLE'; end if;
 if not exists(select 1 from operativo_privado.ruta_multi_pedidos where ruta_id=rid) then raise exception 'RUTA_VACIA'; end if;
 if not exists(select 1 from operativo_privado.ruta_multi_repartidores where ruta_id=rid) then raise exception 'REPARTIDORES_REQUERIDOS'; end if;
 if exists(select 1 from operativo_privado.ruta_multi_repartidores a where a.ruta_id=rid and not exists(select 1 from operativo_privado.repartidores rp join public.perfiles pf on pf.usuario_id=rp.usuario_id where rp.usuario_id=a.usuario_id and rp.activo and pf.rol<>'admin')) then raise exception 'REPARTIDOR_NO_HABILITADO'; end if;
 for p in select pe.* from public.pedidos pe join operativo_privado.ruta_multi_pedidos m on m.pedido_id=pe.id where m.ruta_id=rid order by pe.id for update of pe loop
 if p.regimen_contable<>'entrega_v1' then raise exception 'REGIMEN_CONTABLE_NO_COMPATIBLE'; end if;
 if p.fecha_entrega<>f or p.estado<>'listo_despacho' or p.preparacion_finalizada_en is null then raise exception 'PEDIDO_NO_LISTO'; end if;
 perform 1 from public.items_pedido where pedido_id=p.id order by id for update;
 perform 1 from public.preparacion_items_pedido where pedido_id=p.id order by item_pedido_id for update;
 if not exists(select 1 from public.items_pedido where pedido_id=p.id) or exists(select 1 from public.items_pedido i left join public.preparacion_items_pedido pi on pi.item_pedido_id=i.id
 where i.pedido_id=p.id and (not coalesce(pi.confirmado_explicito,false) or pi.cantidad_preparada is null or pi.importe_linea_operativo is null)) then raise exception 'PRODUCTOS_PENDIENTES'; end if;
 prep:=operativo_privado.estado_preparacion_multi(p.id);
 if prep in ('sin_preparar','sin_stock') then raise exception 'SIN_PREPARAR'; end if;
 select coalesce((select version from operativo_privado.versiones_pedido where pedido_id=p.id),0) into pv;
 if prep='parcial' and not exists(select 1 from operativo_privado.ruta_multi_autorizaciones a where a.ruta_id=rid and a.pedido_id=p.id and a.version=pv and a.cantidades=operativo_privado.cantidades_ruta_multi(p.id)) then raise exception 'PARCIAL_NO_AUTORIZADO'; end if;
 perform operativo_privado.iniciar_operacion(p.id,pv,clave,'ruta_multiple_salir',s);
 insert into operativo_privado.ruta_multi_capacidad values(txid_current(),auth.uid(),rid,p.id,'salir');
 update public.pedidos set estado='en_reparto' where id=p.id;
 delete from operativo_privado.ruta_multi_capacidad where transaccion=txid_current();
 perform operativo_privado.completar_operacion(p.id,pv,clave,'ruta_multiple_salir',s,null,'Salida explícita por ruta',to_jsonb(p),
 jsonb_build_object('estado','en_reparto','preparacion',prep,'cantidades',operativo_privado.cantidades_ruta_multi(p.id)),jsonb_build_object('ruta',rid,'estado','en_reparto'));
 end loop;
 if f is distinct from (clock_timestamp() at time zone 'America/Santiago')::date then raise exception 'PREPARACION_FECHA_NO_HABILITADA'; end if;
 update operativo_privado.rutas_multi set estado='en_reparto',salida_en=clock_timestamp() where id=rid;
 elsif accion in ('entregar','fallida') then
 if r.estado<>'en_reparto' then raise exception 'RUTA_NO_EDITABLE'; end if;
 select pe.* into p from public.pedidos pe join operativo_privado.ruta_multi_pedidos m on m.pedido_id=pe.id where m.ruta_id=rid and pe.id=(s->>'pedido')::uuid;
 if not found then raise exception 'NO_AUTORIZADO'; end if;
 perform 1 from public.clientes where id=p.cliente_id for update nowait;
 insert into operativo_privado.ruta_multi_capacidad values(txid_current(),auth.uid(),rid,p.id,accion);
 if accion='entregar' then
 select * into hist from operativo_privado.historial_operativo where pedido_id=p.id and clave_idempotencia=clave;
 if found then it:=hist.solicitud->'items';
 else select jsonb_agg(jsonb_build_object('item_pedido_id',i.id,'cantidad_entregada',pi.cantidad_preparada) order by i.id) into it
 from public.items_pedido i join public.preparacion_items_pedido pi on pi.item_pedido_id=i.id where i.pedido_id=p.id; end if;
 perform public.confirmar_entrega_todo_correcto(p.id,(s->>'version_pedido')::bigint,clave,it,
 '{"metodo":"por_pagar","efectivo":0,"transferencia":0,"confirmar_por_pagar":true}'::jsonb);
 else perform public.registrar_entrega_fallida(p.id,(s->>'version_pedido')::bigint,clave,s->>'motivo',s->>'observaciones'); end if;
 delete from operativo_privado.ruta_multi_capacidad where transaccion=txid_current();
 elsif accion='cerrar' then
 if r.estado<>'en_reparto' then raise exception 'RUTA_NO_EDITABLE'; end if;
 if exists(select 1 from operativo_privado.ruta_multi_pedidos m join public.pedidos pe on pe.id=m.pedido_id where m.ruta_id=rid and pe.estado not in ('entregado','entrega_fallida')) then raise exception 'PEDIDOS_PENDIENTES'; end if;
 -- La evidencia de cada fallo/venta fue validada por sus barreras actuales.
 -- Congela sólo los pedidos, cantidades, actores y eventos de ESTA ruta.
 update operativo_privado.rutas_multi set estado='cerrada',cierre=antes||jsonb_build_object('cerrada_en',clock_timestamp(),'cerrada_por',auth.uid()) where id=rid;
 end if;
 update operativo_privado.rutas_multi set version=version+1 where id=rid;
 resultado:=jsonb_build_object('ok',true,'ruta',rid,'version',r.version+1);
 if accion='incorporar' then
 resultado:=resultado||jsonb_build_object('modalidad',case when exists(
 select 1 from jsonb_array_elements(antes->'pedidos') x where x->'pedido'->>'estado' in ('entregado','entrega_fallida'))
 then 'incorporacion_extraordinaria' else 'modificacion_controlada' end,'pedidos_agregados',to_jsonb(ids));
 end if;
 insert into operativo_privado.ruta_multi_eventos(clave,ruta_id,actor,solicitud,anterior,resultado)
 values(clave,rid,auth.uid(),s,antes,resultado||jsonb_build_object('snapshot',operativo_privado.snapshot_ruta_multi(rid)));
 return resultado;
end $function$

CREATE OR REPLACE FUNCTION public.reprogramar_no_entregado_administrativo(p_pedido_id uuid, p_version_esperada bigint, p_clave uuid, p_fecha date, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
AS $function$
declare p public.pedidos%rowtype; cp operativo_privado.carga_pedidos%rowtype;
 c operativo_privado.cargas%rowtype; destino operativo_privado.cargas%rowtype;
 solicitud jsonb; inicio jsonb; despues jsonb; seleccion jsonb; respuesta jsonb;
 multi boolean; intento jsonb; fallo operativo_privado.historial_operativo%rowtype;
begin
 if auth.uid() is null or not coalesce(public.es_admin(),false) then raise exception 'NO_AUTORIZADO'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'AISLAMIENTO_NO_COMPATIBLE'; end if;
 if p_fecha is null or not isfinite(p_fecha) or nullif(btrim(p_motivo),'') is null or length(p_motivo)>2000 then raise exception 'OPERACION_INVALIDA'; end if;
 -- Mismo orden global que operar/cerrar; no se toman locks de cliente ni dinero.
 lock table public.pedidos in exclusive mode;
 solicitud:=jsonb_build_object('fecha',p_fecha,'motivo',p_motivo,'contrato',1);
 inicio:=operativo_privado.iniciar_operacion(p_pedido_id,p_version_esperada,p_clave,'reprogramar_no_entregado',solicitud);
 if (inicio->>'reintento')::boolean then return inicio; end if;
 perform operativo_privado.exigir_pedido_reprogramable(p_pedido_id);
 if not public.fecha_entrega_disponible(p_fecha,clock_timestamp())
 or p_fecha>(clock_timestamp() at time zone 'America/Santiago')::date+14 then
 raise exception 'FECHA_ENTREGA_NO_DISPONIBLE'; end if;
 select * into p from public.pedidos where id=p_pedido_id;
 select * into cp from operativo_privado.carga_pedidos where pedido_id=p.id;
 if not found or not cp.incluido then raise exception 'PEDIDO_NO_REPROGRAMABLE'; end if;
 if p_fecha<=cp.fecha or p_fecha<(clock_timestamp() at time zone 'America/Santiago')::date then raise exception 'FECHA_REPROGRAMACION_INVALIDA'; end if;
 -- Locks advisory en orden de fecha, antes de las filas de carga.
 perform pg_advisory_xact_lock(hashtextextended('carga:'||d::text,0))
 from (select cp.fecha d union select p_fecha) fechas order by d;
 -- El lock EXCLUSIVE de pedidos serializa también crear/cerrar/seleccionar
 -- rutas múltiples; sus RPC lo adquieren antes del advisory global multi.
 -- Igual que operar_carga_jornada: materializar sólo destino legacy tras advisory.
 -- Adquirir TODOS los locks de filas por fecha, igual que el trigger de selección;
 -- las lecturas individuales siguientes no introducen otro orden de bloqueo.
 multi:=operativo_privado.fecha_reprogramacion_tiene_rutas_multi(p_fecha);
 if not operativo_privado.fecha_reprogramacion_admite_pedidos(p_fecha) then
 raise exception 'CARGA_NO_EDITABLE'; end if;
 if not multi then
 insert into operativo_privado.cargas(fecha) values(p_fecha) on conflict do nothing;
 end if;
 perform 1 from operativo_privado.cargas
 where fecha in (cp.fecha,p_fecha) order by fecha for update;
 select * into c from operativo_privado.cargas where fecha=cp.fecha;
 if c.estado is distinct from 'cerrada' or p.estado<>'entrega_fallida'
 or p.venta_definitiva_snapshot is not null or p.venta_reconocida_en is not null
 or exists(select 1 from operativo_privado.entregas_definitivas where pedido_id=p.id)
 or p.preparacion_finalizada_en is null then raise exception 'PEDIDO_NO_REPROGRAMABLE'; end if;
 select * into destino from operativo_privado.cargas where fecha=p_fecha;
 if not multi and destino.estado is distinct from 'preparacion' then raise exception 'CARGA_NO_EDITABLE'; end if;
 -- No trasladar una selección sin su intento cerrado y evento de fallo exactos.
 -- La versión del cierre puede preceder otras operaciones auditadas sin cambio
 -- de estado; se enlaza el fallo por su propia versión, no por la versión actual.
 select x into intento from jsonb_array_elements(c.resumen_cierre->'intentos') x
 where x->'pedido'->>'id'=p.id::text;
 select * into fallo from operativo_privado.historial_operativo
 where pedido_id=p.id and operacion='entrega_fallida' order by version desc limit 1;
 if intento is null or fallo.pedido_id is null
 or intento->'pedido' is distinct from to_jsonb(p)
 or intento->'seleccion' is distinct from to_jsonb(cp)
 or intento->'fallo' is distinct from to_jsonb(fallo)
 or jsonb_typeof(intento->'version') is distinct from 'number'
 or (intento->>'version')::bigint>p_version_esperada
 or intento->'motivo' is distinct from to_jsonb(fallo.motivo)
 or fallo.version>(intento->>'version')::bigint
 or fallo.valores_nuevos->>'estado' is distinct from 'entrega_fallida'
 or not exists(select 1 from operativo_privado.historial_cargas h
 where h.fecha=cp.fecha and h.version=c.version and h.resultado=c.resumen_cierre
 and h.solicitud->>'accion'='cerrar') then
 raise exception 'TRAZABILIDAD_INTENTO_INVALIDA'; end if;
 if exists(select 1 from operativo_privado.historial_cargas where fecha=p_fecha and clave=p_clave) then
 raise exception 'CLAVE_IDEMPOTENCIA_EN_USO'; end if;
 despues:=to_jsonb(p)||jsonb_build_object('fecha_entrega',p_fecha,'estado','listo_despacho');
 seleccion:=to_jsonb(cp)||jsonb_build_object('fecha',p_fecha,'incluido',false,'motivo','Pendiente de inclusión tras reprogramación administrativa');
 if multi then seleccion:='null'::jsonb; end if;
 insert into operativo_privado.permiso_reprogramacion values
 (p.id,txid_current(),auth.uid(),to_jsonb(p),despues,to_jsonb(cp),seleccion);
 update public.pedidos set fecha_entrega=p_fecha,estado='listo_despacho' where id=p.id;
 if multi then
 -- Retira sólo la selección viva exacta; la evidencia cerrada permanece intacta.
 delete from operativo_privado.carga_pedidos where pedido_id=p.id;
 else
 update operativo_privado.carga_pedidos set fecha=p_fecha,incluido=false,
 motivo=seleccion->>'motivo' where pedido_id=p.id;
 end if;
 delete from operativo_privado.permiso_reprogramacion where pedido_id=p.id;
 -- La PK de carga_pedidos es por pedido: trasladar libera la asignación vieja.
 -- Su evidencia histórica permanece en resumen_cierre e historial_operativo.
 respuesta:=operativo_privado.completar_operacion(p.id,p_version_esperada,p_clave,
 'reprogramar_no_entregado',solicitud,null,p_motivo,
 jsonb_build_object('pedido',to_jsonb(p),'seleccion',to_jsonb(cp),'cierre',c.resumen_cierre,
 'fallo',to_jsonb(fallo)),
 jsonb_build_object('pedido',(select to_jsonb(pe) from public.pedidos pe where id=p.id),'seleccion',seleccion),
 jsonb_build_object('pedido_id',p.id,'fecha',p_fecha,'estado','listo_despacho','incluido',false));
 if not multi then
 update operativo_privado.cargas set version=version+1 where fecha=p_fecha;
 insert into operativo_privado.historial_cargas(fecha,version,clave,actor,solicitud,anterior,resultado)
 values(p_fecha,destino.version+1,p_clave,auth.uid(),
 solicitud||jsonb_build_object('accion','recibir_reprogramado','pedido_id',p.id),to_jsonb(destino),
 jsonb_build_object('pedido_id',p.id,'version',destino.version+1,'origen',cp.fecha,
 'version_cierre_origen',c.version,'version_fallo',fallo.version,
 'version_operativa',respuesta->'version','clave_operativa',p_clave,
 'seleccion_anterior',to_jsonb(cp),'seleccion_nueva',seleccion));
 end if;
 if not public.fecha_entrega_disponible(p_fecha,clock_timestamp()) then
 raise exception 'FECHA_ENTREGA_NO_DISPONIBLE'; end if;
 return respuesta;
end; $function$
